const CLRS = "6b2737-e08e45-f8f4a6-bdf7b7-3943b7"
  .split("-")
  .map((i) => "#" + i);

const S = 40;

function setup() {
  createCanvas(400, 400);
  // pixelDensity(1);
  describe("animation of tiles by noise");
  frameRate(20);
  noStroke();
	rectMode(CENTER)
  background(0, 0, 8);
}

function draw() {
  background(0, 0, 8);

	for (let y = S/2; y < height; y += S) {		
		for (let x = S/2; x < width; x += S) {
			drawTile(x, y, S);
		}
	}

  showTitle("#minacoding 24/20 10 Minutes")
}

function showTitle(msg) {
	push();
  stroke(0);
	strokeWeight(2);
  fill(255);
  text(msg, 2, 12);
  pop();
}

function drawTile(x, y, s) {
	const n = 5;
	const t = ~~(n * constrain(noise(x, y, frameCount * 0.01) * 1.6 - 0.3, 0, 0.99999));

	push();
	translate(x, y)
	rotate(~~(noise(x * PI, y / PI, frameCount * 0.01) * 4) / 4 * TWO_PI);

	switch (t) {
		case 0:
			fill(CLRS[0]);
			rect(0, 0, s);
			break;

		case 1:
			fill(CLRS[0]);
			rect(0, 0, s);
			fill(CLRS[1]);
			rect(s/4, s/4, s/2);
			break;

		case 2:
			fill(CLRS[2])
			triangle(0, 0, s, s, 0, s);
			break;

		case 3:
			fill(CLRS[3]);
			circle(s/2, s/2, s);
			break;

		case 4:
			fill(CLRS[3]);
			circle(s/2, s/2, s);
			fill(CLRS[4]);
			circle(s/2, s/2, s/2);
			break;

		default:
			console.log(`no defined type ${t}.`);
	}

	pop();
}
